function validate(input) {
  const [{ Votes = [] }] = input;
  const pairs = new Set(), rows = new Map(), abstained = new Set();
  for (const [voter, candidate] of Votes) {
    if (voter === null) return 'Every row needs a voter.';
    const key = `${String(voter).toLowerCase()}|${candidate === null ? '' : String(candidate).toLowerCase()}`;
    if (pairs.has(key)) return `${voter} chooses ${candidate} twice.`;
    pairs.add(key);
    rows.set(voter, (rows.get(voter) ?? 0) + 1);
    if (candidate === null) abstained.add(voter);
  }
  for (const voter of abstained) if (rows.get(voter) > 1) return `${voter} has a null row and other choices.`;
  return null;
}

