function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const voters = small ? ['Ann', 'Ben', 'Cal', 'Dee', 'Eve', 'Fay', 'Gus', 'Hal'] : Array.from({ length: 1200 }, (_, i) => `voter${i + 1}`);
  const candidates = small ? ['Ann', 'Ryan', 'Kathy', 'Lena', 'Omar'] : Array.from({ length: 30 }, (_, i) => `cand${i + 1}`);
  const limit = small ? pick(9) : 2000;
  const Votes = [];
  // Ballots name 1, 2 or 4 candidates, so every share (1, 0.5, 0.25) and every total is exact.
  for (const voter of voters) {
    if (rand() < 0.15) { if (Votes.length + 1 > limit) break; Votes.push([voter, null]); continue; }
    const k = [1, 1, 2, 4][pick(4)];
    if (Votes.length + k > limit) break;
    const pool = candidates.slice();
    for (let i = 0; i < k; i++) Votes.push([voter, pool.splice(pick(pool.length), 1)[0]]);
  }
  for (let i = Votes.length - 1; i > 0; i--) { const j = pick(i + 1); [Votes[i], Votes[j]] = [Votes[j], Votes[i]]; }
  return [{ Votes }];
}
